    v: ["aufstehen=levantarse", "anfangen=empezar", "einkaufen=hacer la compra", "anrufen=llamar por teléfono", "fernsehen=ver la tele", "einschlafen=dormirse", "frühstücken=desayunar", "arbeiten=trabajar", "der Feierabend=el fin de la jornada", "dann=luego"],
